// What makes two documents reports of one speech rather than two speeches.
import { fold } from '../../shared/text.ts';

/**
 * The key two documents reporting one utterance agree on: the words, folded, with
 * punctuation and spacing removed. Outlets differ on quotation marks, ellipses and
 * where they trim — none of which makes it a different thing said.
 *
 * This is exact-match merging on the folded text. It catches the identical quote carried
 * by five outlets, which is the common case; it does not catch a paraphrase or a quote
 * trimmed mid-sentence. Merging those needs the embedding step (#34), and until it exists
 * a near-duplicate stays a separate utterance rather than being merged on a guess.
 */
export function mergeKey(text: string): string {
  return fold(text).replace(/[^\p{L}\p{N}]+/gu, '');
}
