18	/** A tiny seeded PRNG: the same sequence on every machine, unlike Math.random. */
19	function seededRandom(seed: number): () => number {
20	  let state = seed;
21	  return () => {
22	    state = (state + 0x6d2b79f5) | 0;
23	    let t = Math.imul(state ^ (state >>> 15), 1 | state);
24	    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
25	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
26	  };
27	}
