29	/** A ULID minter with a fixed clock and fixed randomness. */
30	export function deterministicIds(startMs = Date.parse('2026-06-14T00:00:00.000Z')): ReturnType<typeof createUlidFactory> {
31	  let tick = 0;
32	  return createUlidFactory({ now: () => startMs + tick++ * 1000, random: seededRandom(20260614) });
33	}
