55	function firstUsefulLine(output: string): string {
56	  // eslint-disable-next-line no-control-regex -- ANSI escapes are exactly what is being stripped
57	  const lines = output.replace(/\u001b\[[0-9;]*m/g, '').split('\n');
58	  const tidy = (line: string) =>
59	    line
60	      .replace(/^[\s\u2718\u25b2\u26c5\ufe0f]+/, '')
61	      .replace(/^\[?(ERROR|WARNING)\]?\s*/i, '')
62	      .trim();
63	
64	  const marked = lines.find((line) => line.includes('\u2718'));
65	  const reason =
66	    tidy(marked ?? '') ||
67	    lines
68	      .map(tidy)
69	      .find((line) => line.length > 12 && !/^wrangler \d|Logs were written|create an issue at|telemetry/.test(line)) ||
70	    '';
71	  return reason.length > 200 ? `${reason.slice(0, 200)}…` : reason;
