// The corpus entities, as both halves see them. Identifiers here are citations:
// once minted they are never reused, renumbered or deleted, and withdrawal is a
// status rather than a removal.

export type FigureStatus = 'active' | 'retired';

export type Figure = {
  /** Slug, minted once at creation from the name of the day; opaque from then on. */
  id: string;
  displayName: string;
  role: string;
  aliases: string[];
  status: FigureStatus;
};

export type SourceKind = 'transcript' | 'press-release' | 'article' | 'broadcast';

/** How a fetched payload ended up, so a source's failure stays legible as a failure. */
export type ExtractionStatus = 'pending' | 'extracted' | 'failed' | 'blocked';

export type Source = {
  id: string;
  url: string;
  publisher: string;
  kind: SourceKind;
  /** When we fetched it — never confused with when the statement was made. */
  fetchedAt: string;
  /** Where the verbatim payload sits in the raw cache. */
  rawKey: string;
  extraction: ExtractionStatus;
};

export type Language = 'he' | 'en';

export type Statement = {
  id: string;
  figureId: string;
  quote: string;
  language: Language;
  /**
   * When it was said. `null` means the source does not establish a date — a distinct
   * state from any date, carried as null the whole way through and omitted (never
   * defaulted) on the wire.
   */
  saidAt: string | null;
  context: string | null;
  sourceId: string;
  topics: string[];
};

/**
 * What the judge said about one pair. Consistent pairs are judgments too: keeping the
 * negatives is what makes the surfacing threshold tunable without re-paying for them.
 */
export type JudgmentKind = 'contradiction' | 'position-shift' | 'consistent';

export type Judgment = {
  id: string;
  figureId: string;
  earlierStatementId: string;
  laterStatementId: string;
  kind: JudgmentKind;
  /** 0–1 confidence that the pair is what `kind` says it is. */
  score: number;
  rationale: string;
  /** The trail: which model, reading which committed prompt, said this. */
  modelVersion: string;
  promptVersion: string;
  createdAt: string;
  /** Set when a later re-analysis replaced this judgment; the record itself stays. */
  supersededBy: string | null;
  /** Whether the product shows it: score over the threshold, kind not `consistent`. */
  surfaced: boolean;
};

export const SURFACED_KINDS: JudgmentKind[] = ['contradiction', 'position-shift'];

/**
 * How far a source pins a date down. Thirty years back it is often a month and no more,
 * and the difference between "March 1998", "12 March 1998" and "we do not know" is three
 * states, not two — a month recorded as its first day is a fact nobody established.
 */
export type DatePrecision = 'day' | 'month' | 'year';

/** When something was said, and how precisely the source establishes it. */
export type SaidAt = { value: string; precision: DatePrecision } | null;

/** Where an utterance was made. A property of the speech act, not of who reported it. */
export type Venue =
  | 'plenary'
  | 'committee'
  | 'interview'
  | 'press-conference'
  | 'op-ed'
  | 'broadcast'
  | 'rally'
  | 'party-forum'
  | 'written-statement'
  | 'other';

/** Who it was addressed to. `null` where the source does not establish one. */
export type Audience = 'general-public' | 'parliament' | 'party-members' | 'foreign-press' | 'professional' | null;

/**
 * One thing said once. Several documents reporting it are several attestations of this
 * one utterance — stored as several records instead, a persona's timeline becomes copies
 * of one sentence and analysis reads the echo as agreement.
 */
export type Utterance = {
  id: string;
  figureId: string;
  /** The fullest wording any attestation carries. */
  text: string;
  language: Language;
  saidAt: SaidAt;
  venue: Venue;
  audience: Audience;
  createdAt: string;
};

/** One document reporting an utterance. */
export type Attestation = {
  id: string;
  utteranceId: string;
  sourceId: string;
  /** The text as this document renders it, even where the utterance holds a fuller one. */
  text: string;
  /** When the document was published — never when the words were said. */
  publishedAt: string | null;
  createdAt: string;
};

// Does the thing we just deployed actually answer? Run at the end of a deploy, against
// the real origins.
//
// Everything the requirements suite proves is proven against a local workerd with local
// D1, R2 and Queues. A missing binding, an unapplied migration, a wrong API origin, a
// Pages project serving the wrong directory — each is invisible to that suite and fatal
// in production. This is the smallest set of reads that tells those apart from a healthy
// deployment.
//
// Usage: node dev/tools/smoke.ts --api https://… --site https://…
import { setTimeout as sleep } from 'node:timers/promises';

const argument = (name: string): string | undefined => {
  const index = process.argv.indexOf(`--${name}`);
  return index === -1 ? undefined : process.argv[index + 1];
};

const api = (argument('api') ?? process.env.API_ORIGIN ?? '').replace(/\/+$/, '');
const site = (argument('site') ?? process.env.SITE_ORIGIN ?? '').replace(/\/+$/, '');

if (!api || !site) {
  console.error('smoke: needs --api and --site (or API_ORIGIN and SITE_ORIGIN in the environment)');
  process.exit(2);
}

/** A deploy takes a moment to propagate; a first 404 is not yet a failed deploy. */
const ATTEMPTS = 5;
const BACKOFF_MS = 3_000;

type Probe = {
  what: string;
  url: string;
  /** Returns null when the response is what it should be, or the reason it is not. */
  check: (response: Response, body: string) => string | null;
};

const PROBES: Probe[] = [
  {
    what: 'the API serves the corpus',
    url: `${api}/api/v1/figures`,
    check: (response, body) => {
      if (response.status !== 200) return `expected 200, got ${response.status}`;
      let parsed: unknown;
      try {
        parsed = JSON.parse(body);
      } catch {
        return `expected JSON, got ${body.slice(0, 120)}`;
      }
      const items = (parsed as { items?: unknown }).items;
      return Array.isArray(items) ? null : 'the body has no items array';
    },
  },
  {
    // Proves it is *our* Worker answering and not a platform placeholder or a parked
    // domain, both of which happily return 200 for the route above.
    what: 'the 404 envelope is ours',
    url: `${api}/api/v1/nope`,
    check: (response, body) => {
      if (response.status !== 404) return `expected 404, got ${response.status}`;
      try {
        const code = (JSON.parse(body) as { error?: { code?: string } }).error?.code;
        return code === 'not_found' ? null : `expected error.code "not_found", got ${JSON.stringify(code)}`;
      } catch {
        return `expected the JSON error envelope, got ${body.slice(0, 120)}`;
      }
    },
  },
  {
    what: 'the site is the built site',
    url: `${site}/`,
    check: (response, body) => {
      if (response.status !== 200) return `expected 200, got ${response.status}`;
      if (!body.includes('<div id="app">')) return 'the HTML is not the built index';
      return body.includes('התבטאויות') ? null : 'the page does not carry the wordmark';
    },
  },
];

async function probe({ what, url, check }: Probe): Promise<boolean> {
  let last = 'never attempted';
  for (let attempt = 1; attempt <= ATTEMPTS; attempt++) {
    try {
      const response = await fetch(url, { headers: { 'user-agent': 'hitbut-smoke' } });
      const failure = check(response, await response.text());
      if (!failure) {
        console.log(`  [ok  ] ${what} — ${url}`);
        return true;
      }
      last = failure;
    } catch (error) {
      last = `request failed: ${String(error)}`;
    }
    if (attempt < ATTEMPTS) await sleep(BACKOFF_MS * attempt);
  }
  console.log(`  [FAIL] ${what} — ${url}`);
  console.log(`         ${last} (after ${ATTEMPTS} attempts)`);
  return false;
}

console.log(`\nhitbut smoke test\n  api:  ${api}\n  site: ${site}\n`);

const outcomes: boolean[] = [];
for (const item of PROBES) outcomes.push(await probe(item));

const failed = outcomes.filter((ok) => !ok).length;
if (failed) {
  console.log(`\n${failed} of ${PROBES.length} probes failed — what shipped is not serving. See issue #36.\n`);
  process.exit(1);
}
console.log(`\nAll ${PROBES.length} probes passed.\n`);
